  <main id="fixture-main">
    <h1>Native Vue fixture</h1>
    <UvInput v-model="name" label="Project name" clearable />
    <UvSwitch v-model="enabled" label="Enabled" />
    <UvSlider v-model="coverage" label="Coverage" value-suffix="%" show-value />
    <UvCombobox v-model="framework" label="Framework" :options="options" />
    <UvDatePicker v-model="releaseDate" label="Release date" locale="en-US" />
    <UvNumberInput v-model="replicas" label="Replicas" :min="1" :max="10" />
    <UvRating v-model="rating" label="Documentation quality" show-value />
