    </UvFormField>
    <UvFieldset legend="Outputs" layout="inline"><UvCheckbox label="Vue" :model-value="true" /><UvCheckbox label="Elements" :model-value="true" /><UvCheckbox label="CDN" :model-value="true" /></UvFieldset>
    <UvStepper v-model="currentStep" :steps="steps" linear />
    <UvCommandPalette mode="inline" :commands="commands" @select="selectedCommand = $event.command.label" />
    <p>{{ selectedCommand }}</p>
    <UvTimeline label="Batch 04 progress" :items="timeline" />
    <UvCalendar v-model="calendarDate" locale="en-US" />
    <UvFileUpload label="Package artifact" accept=".zip,.tgz" />
    <UvTable caption="Batch status" :columns="columns" :rows="rows" selectable />
    <UvToast v-model:items="toastItems" position="inline" />
    <UvDivider label="Actions" />
    <div class="actions">
      <UvButton @click="drawerOpen = true">Open drawer</UvButton>
      <UvDropdownMenu v-model="menuOpen" label="More actions">
        <button type="button" role="menuitem">Preview</button>
        <button type="button" role="menuitem">Duplicate</button>
      </UvDropdownMenu>
    </div>
    <UvDrawer v-model="drawerOpen" title="Vue drawer" description="Rendered from the native package."><p>Drawer content remains normal Vue markup.</p></UvDrawer>

