    <UvNavigationMenu v-model="batch8Nav" label="Fixture navigation" items-json='[{"id":"components","label":"Components","href":"#components"},{"id":"guides","label":"Guides","children":[{"id":"install","label":"Install","href":"#install"}]}]' />
    <UvMenubar label="Fixture menu" items-json='[{"id":"file","label":"File","children":[{"id":"new","label":"New"}]}]' />
    <UvBottomNavigation v-model="batch8Bottom" label="Destinations" items-json='[{"id":"home","label":"Home","icon":"⌂"},{"id":"search","label":"Search","icon":"⌕"}]' />

