    <UvDescriptionList label="Package details" bordered items-json='[{"term":"Package","description":"@universal-vue/vue"},{"term":"License","description":"MIT"}]' />
    <UvStat label="Components" :value="70" :trend="5" trend-direction="up" trend-label="this batch" />
    <UvCodeBlock code="import { UvButton } from '@universal-vue/vue'" language="ts" line-numbers />
    <UvListbox v-model="batch10Listbox" multiple searchable label="Frameworks" options-json='[{"label":"Vue","value":"vue"},{"label":"React","value":"react"}]' />
    <UvTransferList v-model="batch10Transfer" items-json='[{"id":"vue","label":"Vue"},{"id":"react","label":"React"}]' source-label="Available" target-label="Enabled" />

